with RecursiveSubQuestions as (
    select 
        p.Id,
        p.Title,
        p.OwnerUserId,
        p.CreationDate, 
        p.Tags,
        p.Score,
        p.ViewCount,
        case when p.AcceptedAnswerId is not null then 1 else 0 end as HasAcceptedAnswer,
        u.Reputation,
        array_length(string_to_array(coalesce(p.Tags,''), '') , 1)::int as TagElementCount - 2 as TagCount0, --removes initial empty and trailing but tedious/ complicated counts tags (corrected later)

    -- Access Tagged posts after replacing >< inside removing <> from tags signal wrap inside )
    from Posts p
    left join Users u on u.Id = p.OwnerUserId
    where p.PostTypeId = 1 /* questions */

    union all 

    select
        child.Id,
        child.Title,
        child.OwnerUserId,
        child.CreationDate,
        child.Tags,
        child.Score,
        child.ViewCount,
        case when child.AcceptedAnswerId is not null then 1 else 0 end as HasAcceptedAnswer,
        latest.Reputation,
        datasetperforming.Sub.TagCount  
